// ─── File: ShardingDemo.java ───
// Runnable demo: route accounts by RANGE, HASH, and GEOGRAPHIC; show distribution + scatter-gather.
package com.bank.sharding;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ShardingDemo {

    private static final Logger log = Logger.getLogger("Sharding");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Accounts: ids increase over time; mix of regions.
        List<Account> accounts = new ArrayList<>();
        for (int i = 1; i <= 12; i++)
            accounts.add(new Account("ACC" + (1000 + i), new BigDecimal("50000"),
                    i % 3 == 0 ? "EU" : "IN"));

        // HASH sharding → even spread (no hot shard).
        demo("HASH", accounts);
        // RANGE sharding → newest ids pile onto the last shard (HOT SHARD).
        demo("RANGE", accounts);
        // GEOGRAPHIC sharding → data placed by region (residency + latency).
        demo("GEOGRAPHIC", accounts);
    }

    static void demo(String strategy, List<Account> accounts) {
        ShardRouter router = new ShardRouter(strategy, 4);
        for (Account a : accounts) router.shardFor(a).insert(a);
        log.info(() -> strategy + " distribution: " + router.distribution());
        // Scatter-gather: total count must query EVERY shard and sum.
        int total = router.scatterGatherCount();
        log.info(() -> strategy + " scatter-gather total accounts = " + total);
    }
}

// ─── model/Account.java ───
class Account {
    final String accountId; final BigDecimal balance; final String region;
    Account(String id, BigDecimal bal, String region) { accountId=id; balance=bal; this.region=region; }
}

// ─── node/Shard.java (one independent database node) ───
class Shard {
    final int id; final String region;
    final Map<String, Account> rows = new HashMap<>();
    Shard(int id, String region) { this.id = id; this.region = region; }
    void insert(Account a) { rows.put(a.accountId, a); }
    int count() { return rows.size(); }
}

// ─── router/ShardRouter.java (maps shard key → shard by strategy) ───
class ShardRouter {
    private final String strategy;
    private final List<Shard> shards = new ArrayList<>();
    ShardRouter(String strategy, int n) {
        this.strategy = strategy;
        for (int i = 0; i < n; i++) shards.add(new Shard(i, i < n/2 ? "IN" : "EU"));
    }
    Shard shardFor(Account a) {
        switch (strategy) {
            case "HASH":                                   // even distribution
                return shards.get(Math.floorMod(a.accountId.hashCode(), shards.size()));
            case "RANGE": {                                // contiguous id ranges → hot shard risk
                int idNum = Integer.parseInt(a.accountId.substring(3));
                int perShard = 4;                           // ids 1001-1004→s0, 1005-1008→s1, ...
                return shards.get(Math.min((idNum - 1001) / perShard, shards.size() - 1));
            }
            case "GEOGRAPHIC":                              // route by region
                return shards.stream().filter(s -> s.region.equals(a.region)).findFirst()
                        .orElse(shards.get(0));
            default: throw new IllegalArgumentException(strategy);
        }
    }
    String distribution() {
        StringBuilder sb = new StringBuilder();
        for (Shard s : shards) sb.append("shard").append(s.id)
                .append("(").append(s.region).append(")=").append(s.count()).append(" ");
        return sb.toString().trim();
    }
    // Scatter-gather: fan out to EVERY shard and merge — expensive at scale.
    int scatterGatherCount() { return shards.stream().mapToInt(Shard::count).sum(); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
